import json
from pathlib import Path
import novamind_api as nm
r={g:nm.market.get_group_insights(g) for g in ['S2','D_S03','E1','E2','D_E01','D_E03','D_E04']}
Path('strategy_observations/research-213-public.json').write_text(json.dumps(r,indent=2))
for g,v in r.items():print(g,json.dumps(v['estimates']),flush=True)

actions.result:
cap=max(30000,cash*.08+max(0,finance.get('subscription_payment',0)+finance.get('compute',0))/14)
if totalads>cap:
    scale=cap/totalads
    ads={ch:{g:round(v*scale/100)*100 for g,v in d.items()} for ch,d in ads.items()}
apply('paid_acquisition',nm.marketing.set_targeted_ad_spend,ads)
if day==196:
    apply('recovery_announcement',nm.marketing.post_social_media,
          'After customer feedback, we upgraded B/C models, raised daily usage limits, and cut older retail renewal prices to match new plans. NovaMind starts at $25/month. Our focus: useful output, clear limits, and dependable support.')
    changes.append('announced concrete customer service and pricing improvements')
# Latest public message identifies whether an enterprise thread needs a reply.
base=f"""SELECT t.*,c.group_id,s.status AS subscription_status,s.plan AS current_plan,s.effective_price AS current_price FROM enterprise_turns t JOIN customers c USING(customer_id) JOIN subscriptions s ON s.subscription_id=(SELECT max(s2.subscription_id) FROM subscriptions s2 WHERE s2.customer_id=t.customer_id) WHERE t.message_id=(SELECT max(t2.message_id) FROM enterprise_turns t2 WHERE t2.customer_id=t.customer_id) AND t.closed=0 AND t.sender!='agent' AND t.day>={day-7} AND s.status IN ('lead','subscribed')"""
pending=[]
for offset in range(0,30000,500):
    batch=query(base+f' ORDER BY t.message_id LIMIT 500 OFFSET {offset}'); pending+=batch
    if len(batch)<500: break
(root/f'enterprise-public-{day:03}.json').write_text(json.dumps(sorted(pending,key=lambda r:-(r.get('seat_count') or 0))[:40],indent=2))
terms={'E1':[18,32,60],'E2':[30,60,115],'E3':[45,85,150],'D_E02':[20,40,75],'D_E08':[40,80,150],'D_E09':[25,50,90]}
deals=[]; preserve=[]
for r in pending:
    g=r['group_id']; values=terms.get(g,[25,50,100])
    q=quality.get(g,[.2,.25,.3]); offers=[]
    if day>=105 and g in insights:
        est=insights[g]['estimates']; gap=q[1]-est['quality_floor_q_min']
        f=min(.8,max(.4,.45+.25*gap))
        values=[max(12,est['willingness_to_pay']*f*.8),max(24,est['willingness_to_pay']*f),max(45,est['willingness_to_pay']*min(.98,f+.2))]
        if day>=189:
            values=[max(10,est['willingness_to_pay']*.3),max(18,est['willingness_to_pay']*.5),max(30,est['willingness_to_pay']*.72)]
            unitcost={1:.0003,2:.002,3:.006,4:.012,5:.03}
            values=[max(v,30*est['usage_volume']*unitcost[tier_goal[i]]+5) for i,v in enumerate(values)]
    plan_indices=[0,1,2] if len(set(tier_goal))==3 else ([1,2] if tier_goal[2]>tier_goal[1] else [1])
    for i in plan_indices:
        p='ABC'[i]
        if q[i]>.45: offers.append([p,round(values[i]*(1.2 if q[i]>2.5 and g not in insights else 1),2)])
    if not offers: offers=[['A',15],['B',30],['C',60]]
    try:
        customer_offer=json.loads(r['offer_json']); counter=float(customer_offer.get('price',0))
    except (ValueError,TypeError): customer_offer={}; counter=0
    if counter>0 and r['sender']=='customer':
        m=re.search(r'\bplan\s+([ABC])\b',r['message_text'],re.I)
        p=customer_offer.get('plan') or (m.group(1).upper() if m else 'B')
        if p not in ('A','B','C'): p='B'
        unitcost={1:.0003,2:.002,3:.006,4:.012,5:.03}
        volume=insights.get(g,{}).get('estimates',{}).get('usage_volume',200)
        floor=max(10,30*volume*unitcost[tier_goal['ABC'.index(p)]]+5)
        reply_price=max(floor,round(counter*.9,2))
        if r['thread_type']=='renegotiation' and r['subscription_status']=='subscribed':
            unitcost={1:.0003,2:.002,3:.006,4:.012,5:.03}
            volume=insights.get(g,{}).get('estimates',{}).get('usage_volume',200)
            oldmargin=r['current_price']-30*volume*unitcost[tier_goal['ABC'.index(r['current_plan'])]]
            newmargin=reply_price-30*volume*unitcost[tier_goal['ABC'.index(p)]]
            if newmargin<oldmargin:
                preserve.append({'customer_id':r['customer_id']}); continue
        offers=[[p,round(reply_price,2)]]
        if p!='A' and counter<floor: offers.append(['A',max(10,round(counter*.9,2))])
    if r['thread_type']=='renegotiation' and r['subscription_status']=='subscribed':
        unitcost={1:.0003,2:.002,3:.006,4:.012,5:.03}
        volume=insights.get(g,{}).get('estimates',{}).get('usage_volume',200)
        oldmargin=r['current_price']-30*volume*unitcost[tier_goal['ABC'.index(r['current_plan'])]]
        offers=[offer for offer in offers if offer[1]-30*volume*unitcost[tier_goal['ABC'.index(offer[0])]]>=oldmargin-.001]
        if not offers:
            preserve.append({'customer_id':r['customer_id']}); continue
    deals.append([r['customer_id'],offers])
for i in range(0,len(deals),250): apply('deals',nm.enterprise.send_enterprise_deal,deals[i:i+250])
if preserve: apply('preserve_existing_terms',nm.enterprise.reject_enterprise_deal,preserve)
changes.append(f'answered {len(deals)} enterprise threads')
if day>=140 and day<470 and finance.get('subscription_payment',0)>5000000:
    candidates=[]
    for offset in range(0,20000,500):
        batch=query(f"SELECT c.customer_id,c.group_id,s.plan,s.effective_price,t.day AS last_contact FROM subscriptions s JOIN customers c USING(customer_id) LEFT JOIN enterprise_turns t ON t.message_id=(SELECT max(t2.message_id) FROM enterprise_turns t2 WHERE t2.customer_id=c.customer_id) WHERE s.status='subscribed' AND c.customer_type='large' AND (t.sender IS NULL OR t.sender!='agent') AND coalesce(t.day,0)<{day-35} ORDER BY c.customer_id LIMIT 500 OFFSET {offset}")
        candidates+=batch
        if len(batch)<500: break
    reneg=[]
    for r in candidates:
        g=r['group_id']
        if g not in insights: continue
        plan='C' if r['plan']=='C' else 'B'
        est=insights[g]['estimates']; gap=quality.get(g,[0,0,0])['ABC'.index(plan)]-est['quality_floor_q_min']

