\"\"\"Cash policies derived exclusively from saved public game observations.\"\"\"
import json
from pathlib import Path

TRENDS={'S1':(6.031-.454)/(192-94),'S2':(6.778-.638)/(213-94),
        'E1':(7.407-.843)/(213-108),'E2':(7.748-1.289)/(213-108),
        'D_E01':(6.535-.982)/(213-101),'D_E03':(6.683-1.014)/(213-108),
        'D_E04':(6.591-.994)/(213-108),'E3':(7.236-1.051)/(227-108),
        'D_E08':(6.48-.901)/(227-108),'D_E07':(5.728-.794)/(192-108)}
FRESH_GROUPS=['S1','S2','E1','E2','E3','D_E07','D_E08']

def make_baseline(root,insights):
    path=root/'compute_quality_baseline.json'
    if path.exists():return json.loads(path.read_text())
    public=json.loads((root/'before-231.json').read_text())
    result={}
    for group,trend in TRENDS.items():
        info=insights[group]
        floor=info['estimates']['quality_floor_q_min']+trend*(231-info['_research_day'])
        surplus=public['quality'][group][2]-floor
        result[group]={'trend':trend,'floor_at_231':floor,
                       'baseline_surplus':surplus,'required_surplus':max(2.5,surplus+.5)}
    path.write_text(json.dumps(result,indent=2))
    return result

def entry_price(root,day,acquired,insights):
    path=root/'entry_price_test_decision.json'
    if path.exists():return json.loads(path.read_text())
    assert day>=252
    baseline=json.loads((root/'before-245.json').read_text())['acquired']
    def row_score(rows,quota):
        rows=[r for r in rows if r['group_id']=='S1' and r['acquisition_source']=='content_marketing']
        if not rows:return {'leads':0,'contribution_per_lead':0}
        row=rows[0];n=row.get('converted') or 0
        if not n:return {'leads':row['leads'],'contribution_per_lead':0}
        volume=insights['S1']['estimates']['usage_volume']
        cost=30*sum((row.get('share_'+p) or 0)*min(volume,q)*u for p,q,u in zip('ABC',[150,quota,250],[.0003,.006,.012]))
