                'price':row['price'],'monthly_margin':row['price']-cost-2,
                'contribution_per_lead':n/max(1,row['leads'])*(row['price']-cost-2)}
    old=row_score(baseline,150);new=row_score(acquired,100)
    keep=new['leads']>=200 and new['contribution_per_lead']>1.1*old['contribution_per_lead']
    result={'decision_day':day,'new_cohort_B_price':25. if keep else 35.,'baseline_B35':old,'test_B25':new}
    path.write_text(json.dumps(result,indent=2))
    return result

def efficiency_checks(root,day,quality,config,insights):
    baseline=make_baseline(root,insights)
    multiplier={1:.6,2:.75,3:.9,4:1.,5:1.1}
    checks={}
    for group,record in baseline.items():
        info=insights[group]
        floor=info['estimates']['quality_floor_q_min']+record['trend']*(day-info['_research_day'])
        candidate=quality[group][2]*.9/multiplier[config['tier_C']]
        margin=candidate-floor
        checks[group]={'candidate_quality_C3':candidate,'estimated_floor':floor,
                       'surplus':margin,'required_surplus':record['required_surplus'],
                       'pass':margin>=record['required_surplus']}
    return checks

